"""Build explicit, script-free state canvases for MoDao HTML import."""
from pathlib import Path
from html import escape
from build import CSS

ROOT = Path(__file__).resolve().parent
OUT = ROOT / "modao_pages"
OUT.mkdir(exist_ok=True)

def a(target, label, primary=False):
    return f'<a class="button {"primary" if primary else ""}" href="{target}.html">{label}</a>'

def card(title, text, actions="", extra=""):
    return f'<article class="card">{extra}<h3>{title}</h3><p>{text}</p><div class="actions">{actions}</div></article>'

def head(kicker, title, desc, action=""):
    return f'<div class="page-head"><div><div class="eyebrow">{kicker}</div><h1>{title}<span class="orange">.</span></h1><p>{desc}</p></div>{action}</div>'

def tabs(items, selected):
    return '<nav class="tabs">'+''.join(f'<a class="{"active" if key==selected else ""}" href="{key}.html">{label}</a>' for key,label in items)+'</nav>'

report_tabs=[('report-overview','比赛概览'),('report-rounds','回合复盘'),('report-utility','道具与生存'),('report-data','详细数据')]
