NAV=[('index','⌗　总览'),('replays','▤　我的复盘'),('training','◎　瞄准训练'),('lobbies','♧　校园车队'),('friends','♙　玩家与好友'),('profile','◯　个人中心')]

def document(key,name,body):
    nav=''.join(f'<a class="{"active" if x==key else ""}" href="{x}.html">{label}</a>' for x,label in NAV)
    return f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(name)} · CS Demo Master 原型</title><style>{CSS}</style></head><body><div class="shell"><aside class="sidebar"><a class="brand" href="index.html"><b>⌖</b> CS DEMO <small>MASTER</small></a><div class="eyebrow">PLAYER WORKSPACE / 01</div><nav class="nav">{nav}</nav><div class="sidebar-note">◎　界面原型演示数据<br>按流程点击画布按钮</div></aside><div class="main"><header class="top"><span>工作台　/　{escape(name)}</span><span>{a('profile','Demo Player')}　{a('login','登录 / 注册')}</span></header><main class="content">{body}<div class="footer">CS DEMO MASTER / 软件工程课程界面原型 · 示例内容</div></main></div></div></body></html>'''

for key,name,body in PAGES:
    (OUT / f'{key}.html').write_text(document(key,name,body),encoding='utf-8')
(ROOT / 'MODAO-v2-PAGE-MAP.md').write_text('# 墨刀 v2 画布清单\n\n'+ '\n'.join(f'- `{key}.html` — {name}' for key,name,_ in PAGES)+'\n',encoding='utf-8')
print(f'Generated {len(PAGES)} script-free state pages in {OUT}')
